const type = response.headers.find(header => header.name.toLowerCase() === 'content-type');
const coding = response.headers.find(header => header.name.toLowerCase() === 'content-encoding');
const mime = type ? type.value.split(';')[0].trim().toLowerCase() : '';
const charset = type && /charset\s*=\s*"?([^;"\s]+)/i.exec(type.value);
if (!(mime === 'application/json' || (mime.startsWith('application/') && mime.endsWith('+json')))) {
  console.log('skipped: response is not JSON');
} else if (coding && coding.value.trim() && coding.value.trim().toLowerCase() !== 'identity') {
  console.log('skipped: encoded response body');
} else if (charset && !/^utf-?8$/i.test(charset[1])) {
  console.log('skipped: response is not UTF-8');
} else if (!response.bodyBase64) {
  console.log('skipped: empty response body');
} else {
  const data = JSON.parse(decodeText(response.bodyBase64));
  if (data !== null && typeof data === 'object' && !Array.isArray(data)) {
    data.debugPlugin = 'example-json-response';
    response.bodyBase64 = encodeText(JSON.stringify(data, null, 2));
    console.log('added debugPlugin to JSON response');
  } else {
    console.log('skipped: JSON root is not an object');
  }
}
